Proof.
ltac2:(KReplay.run1 (kr_t_LbB_PmWNT ()) [] "h01zh11Eh22bch32blh41ch54entsh65ents'h71pp;2p;1p;4p;3p;6g006Pj23Tg008Xj1FTg00:lj1=Tg00BQj44Tg00XEj37Tg007Uj1;Tg008:j1>Tg00B4j20Tg00f\j15Tg00A7j26Tg00Glj1<Tg00UOj1@Tg00Whj21Tg00n6j1?Tg012Ej1:Tg00VTj2ETg004ij69Tg01Afj1DTg00SYj2CTg01Bfj2BTg00IUj4ATg00JLR0P0f1R1f0R2C4p=8P0P0P1P2CAp=2g00Jj1300R3/30,30,30#FR41334R5f4R6#=P3P4f3R7f2R8'8P1C437P0g00KbR9#;#;#;#>R:P3P41867R7P1C4R1,24R;'0#5g00LGR<P0g00LgR=,6;P=%>9R9n0100000020000'0f5R;#<#@R>'1%?;R?'1f6R@#:9702X00P0%=;RA,24RB,0:#5P<P016B=P=P9n0100000020000'0/1>/1?P3P418;6P8C4,24R6,0:#5P<P0166=P=P9n0100000020000'0%<@#@R6'1%?@R@'1RB=702X00P5P3P4P7P8C4R81242R7,0:#5P<P0167=P=P9n0100000020000'0/16/1@970BX751248R8,0:#5P<P0168=P=P9n0100000020000'0/1>/1?,E0PAP2E9%:;%D;E91C;1#:1B;1E9W1X64W5X20X30W4o"). Qed.

Section Keep.
  Context {HCEIL : HeapCeil}.

  Lemma pmc_keep_m2 : forall (p : Z) L L' m m' (c : pmc),
    @umapx AC_A ASEGS LY_A MI_A 24 Z (nval24 ASEGS) L m (p + O_M1) (t3a (c_m1 c)) (t3b (c_m1 c)) (t3c (c_m1 c)) ->
    @umapx AC_A ASEGS LY_A MI_A 24 Z (nval24 ASEGS) L m (p + O_M3) (t3a (c_m3 c)) (t3b (c_m3 c)) (t3c (c_m3 c)) ->
    @vec_opnd AC_A ASEGS LY_A MI_A L m (p + O_V1) (t3a (c_v1 c)) (t3b (c_v1 c)) (t3c (c_v1 c)) ->
    @vec32 AC_A ASEGS LY_A MI_A L m (p + O_V2) (t3a (c_v2 c)) (t3b (c_v2 c)) (t3c (c_v2 c)) ->
    @vec32 AC_A ASEGS LY_A MI_A L m (p + O_V3) (t3a (c_v3 c)) (t3b (c_v3 c)) (t3c (c_v3 c)) ->
    pmc_sh m c ->
    (forall a, p + O_M1 <= a < p + PARSER_SIZE -> (a < p + O_M2 \/ p + O_M3 <= a) -> m' (Z_to_bv 64 a) = m (Z_to_bv 64 a)) ->
    (forall A n a, In (A, n) (rest_m2 c) -> A <= a < A + n -> m' (Z_to_bv 64 a) = m (Z_to_bv 64 a)) ->
    (forall A n sbs, In (A, n) (rest_m2 c) -> Z.of_nat (length sbs) <= nsh n -> SHAD m A sbs -> SHAD m' A sbs) ->
    (forall b, In b (rest_m2 c) -> In b L -> In b L') ->
    @umapx AC_A ASEGS LY_A MI_A 24 Z (nval24 ASEGS) L' m' (p + O_M1) (t3a (c_m1 c)) (t3b (c_m1 c)) (t3c (c_m1 c))
    /\ @umapx AC_A ASEGS LY_A MI_A 24 Z (nval24 ASEGS) L' m' (p + O_M3) (t3a (c_m3 c)) (t3b (c_m3 c)) (t3c (c_m3 c))
    /\ umap_sh m' 24 (c_m1 c) /\ umap_sh m' 24 (c_m3 c)
    /\ @vec_opnd AC_A ASEGS LY_A MI_A L' m' (p + O_V1) (t3a (c_v1 c)) (t3b (c_v1 c)) (t3c (c_v1 c)) /\ vsh_opnd m' (c_v1 c)
    /\ @vec32 AC_A ASEGS LY_A MI_A L' m' (p + O_V2) (t3a (c_v2 c)) (t3b (c_v2 c)) (t3c (c_v2 c)) /\ vsh32 m' (c_v2 c)
    /\ @vec32 AC_A ASEGS LY_A MI_A L' m' (p + O_V3) (t3a (c_v3 c)) (t3b (c_v3 c)) (t3c (c_v3 c)) /\ vsh32 m' (c_v3 c).
  Proof.
    intros p L L' m m' c U1 U3 V1 V2 V3 SHc HEQ BEQ SEQ LIVE.
    set (P1 := umap_blocks 24 (t3a (c_m1 c)) (t3b (c_m1 c)) (t3c (c_m1 c))).
    set (P3 := umap_blocks 24 (t3a (c_m3 c)) (t3b (c_m3 c)) (t3c (c_m3 c))).
    set (P4 := vec_opnd_blocks (t3a (c_v1 c)) (t3c (c_v1 c))).
    set (P5 := if t3a (c_v2 c) =? 0 then [] else [(t3a (c_v2 c), 4 * t3c (c_v2 c))]).
    set (P6 := if t3a (c_v3 c) =? 0 then [] else [(t3a (c_v3 c), 4 * t3c (c_v3 c))]).
    set (P7 := c_tr c).
    assert (ER : rest_m2 c = P1 ++ P3 ++ P4 ++ P5 ++ P6 ++ P7) by reflexivity.
    assert (I1 : forall b, In b P1 -> In b (rest_m2 c)) by (intros b Hb; rewrite ER, !in_app_iff; tauto).
    assert (I3 : forall b, In b P3 -> In b (rest_m2 c)) by (intros b Hb; rewrite ER, !in_app_iff; tauto).
    assert (I4 : forall b, In b P4 -> In b (rest_m2 c)) by (intros b Hb; rewrite ER, !in_app_iff; tauto).
    assert (I5 : forall b, In b P5 -> In b (rest_m2 c)) by (intros b Hb; rewrite ER, !in_app_iff; tauto).
    assert (I6 : forall b, In b P6 -> In b (rest_m2 c)) by (intros b Hb; rewrite ER, !in_app_iff; tauto).

    assert (UK : forall NS (V : Type) (nval : mem -> Z -> V -> Prop)
      (nval_agree : forall M M' p v, nval M p v -> HRepFacts.agree_on M M' (p + 20) (NS - 20) -> 0 < p -> p + NS <= 2 ^ 47 -> nval M' p v)
      (HNS : 24 <= NS) off bl bc ents,
      O_M1 <= off -> off + 40 <= PARSER_SIZE -> (off + 40 <= O_M2 \/ O_M3 <= off) ->
      (forall b, In b (umap_blocks NS bl bc ents) -> In b (rest_m2 c)) ->
      @umapx AC_A ASEGS LY_A MI_A NS V nval L m (p + off) bl bc ents ->
      @umapx AC_A ASEGS LY_A MI_A NS V nval L' m' (p + off) bl bc ents).
    { intros NS V nval nval_agree HNS off bl bc ents Ho1 Ho2 Ho3 IB U.
      eapply (umapx_agree ASEGS LY_A MI_A NS V nval nval_agree HNS); [exact U | |].
      - intros a Ha. unfold umap_foot in Ha. destruct Ha as [Ha|[(Hbc & Ha)|(q & Hq & Ha)]].
        + apply HEQ; unfold O_M1, O_M2, O_M3, PARSER_SIZE in *; lia.
        + assert (Hin : In (bl, 8 * bc) (umap_blocks NS bl bc ents)).
          { unfold umap_blocks. apply in_app_iff. left. destruct (Z.eqb_spec bc 0); [lia | left; reflexivity]. }
          exact (BEQ bl (8 * bc) a (IB _ Hin) Ha).
        + assert (Hin : In (q, NS) (umap_blocks NS bl bc ents)).
          { unfold umap_blocks. apply in_app_iff. right.
            apply in_map_iff in Hq. destruct Hq as ([q' kv] & Eq & Hin). cbn in Eq. subst q'.
            apply in_map_iff. exists (q, kv). split; [reflexivity | exact Hin]. }
          exact (BEQ q NS a (IB _ Hin) Ha).
      - intros b n0 Hb Hl. apply LIVE; [exact (IB _ Hb) | exact Hl]. }
    pose proof SHc as (SH1 & SH2 & SH3 & SH4 & SH5 & SH6).
    split; [apply (UK 24 Z (nval24 ASEGS) (nval24_agree ASEGS) ltac:(lia) O_M1); [unfold O_M1; lia | unfold O_M1, PARSER_SIZE; lia | left; unfold O_M1, O_M2; lia | exact I1 | exact U1]|].
    split; [apply (UK 24 Z (nval24 ASEGS) (nval24_agree ASEGS) ltac:(lia) O_M3); [unfold O_M1, O_M3; lia | unfold O_M3, PARSER_SIZE; lia | right; lia | exact I3 | exact U3]|].

    assert (USH : forall NS (V : Type) (t : Z * Z * list (Z * (Z * V))),
      (forall b, In b (umap_blocks NS (t3a t) (t3b t) (t3c t)) -> In b (rest_m2 c)) ->
      umap_sh m NS t -> umap_sh m' NS t).
    { intros NS V [[bl bc] ents] IB [SB SN]. unfold umap_sh. cbn [t3a t3b t3c fst snd] in *. split.
      - intros Hbc. pose proof (SB Hbc) as AD. destruct AD as [Hn SH]. split; [exact Hn|].
        assert (Hin : In (bl, 8 * bc) (umap_blocks NS bl bc ents)).
        { unfold umap_blocks. apply in_app_iff. left. destruct (Z.eqb_spec bc 0); [lia | left; reflexivity]. }
        eapply (SEQ bl (8 * bc)); [exact (IB _ Hin) | rewrite shadow_of_length by lia; lia | exact SH].
      - intros q k v Hin. destruct (SN q k v Hin) as [Hn SH]. split; [exact Hn|].
        assert (Hin' : In (q, NS) (umap_blocks NS bl bc ents)).
        { unfold umap_blocks. apply in_app_iff. right. apply in_map_iff. exists (q, (k, v)). split; [reflexivity | exact Hin]. }
        eapply (SEQ q NS); [exact (IB _ Hin') | rewrite shadow_of_length by lia; lia | exact SH]. }
    split; [exact (USH 24 Z (c_m1 c) I1 SH1)|].
    split; [exact (USH 24 Z (c_m3 c) I3 SH3)|].

    split; [| split; [| split; [| split; [| split]]]].
    - eapply vec_opnd_live; [eapply vec_opnd_frame; [exact V1|] |].
      + intros a Ha. unfold vec_opnd_fp, zwin in Ha. apply HEQ; unfold O_V1, O_M1, O_M2, O_M3, PARSER_SIZE in *; lia.
      + intros Hb Hl. apply LIVE; [| exact Hl]. apply I4. subst P4. unfold vec_opnd_blocks. destruct (Z.eqb_spec (t3a (c_v1 c)) 0); [lia | left; reflexivity].
    - intros Hb. pose proof V1 as (_ & _ & _ & Hlen & _).
      assert (Hin : In (t3a (c_v1 c), OPND_SZ * t3c (c_v1 c)) (rest_m2 c)).
      { apply I4. subst P4. unfold vec_opnd_blocks. destruct (Z.eqb_spec (t3a (c_v1 c)) 0); [lia | left; reflexivity]. }
      eapply (SEQ (t3a (c_v1 c)) (OPND_SZ * t3c (c_v1 c))); [exact Hin | | exact (SH4 Hb)].
      rewrite cc_gen_length by (unfold OPND_SZ; lia). lia.
    - eapply vec32_live; [eapply vec32_frame; [exact V2|] |].
      + intros a Ha. unfold vec32_fp, zwin in Ha. destruct Ha as [Ha|(Hb & Ha)].
        * apply HEQ; unfold O_V2, O_V1, O_M1, O_M2, O_M3, PARSER_SIZE in *; lia.
        * pose proof V2 as (_ & _ & _ & Hlen & _).
          assert (Hin : In (t3a (c_v2 c), 4 * t3c (c_v2 c)) (rest_m2 c)) by (apply I5; subst P5; destruct (Z.eqb_spec (t3a (c_v2 c)) 0); [lia | left; reflexivity]).
          apply (BEQ (t3a (c_v2 c)) (4 * t3c (c_v2 c)) a Hin). unfold Zlen in *. lia.
      + intros Hb Hl. apply LIVE; [| exact Hl]. apply I5. subst P5. destruct (Z.eqb_spec (t3a (c_v2 c)) 0); [lia | left; reflexivity].
    - intros Hb. pose proof V2 as (_ & _ & _ & Hlen & _).
      assert (Hin : In (t3a (c_v2 c), 4 * t3c (c_v2 c)) (rest_m2 c)) by (apply I5; subst P5; destruct (Z.eqb_spec (t3a (c_v2 c)) 0); [lia | left; reflexivity]).
      eapply (SEQ (t3a (c_v2 c)) (4 * t3c (c_v2 c))); [exact Hin | | exact (SH5 Hb)].
      rewrite cc_gen_length by (unfold Zlen in *; lia). lia.
    - eapply vec32_live; [eapply vec32_frame; [exact V3|] |].
      + intros a Ha. unfold vec32_fp, zwin in Ha. destruct Ha as [Ha|(Hb & Ha)].
        * apply HEQ; unfold O_V3, O_V1, O_M1, O_M2, O_M3, PARSER_SIZE in *; lia.
        * pose proof V3 as (_ & _ & _ & Hlen & _).
          assert (Hin : In (t3a (c_v3 c), 4 * t3c (c_v3 c)) (rest_m2 c)) by (apply I6; subst P6; destruct (Z.eqb_spec (t3a (c_v3 c)) 0); [lia | left; reflexivity]).
          apply (BEQ (t3a (c_v3 c)) (4 * t3c (c_v3 c)) a Hin). unfold Zlen in *. lia.
      + intros Hb Hl. apply LIVE; [| exact Hl]. apply I6. subst P6. destruct (Z.eqb_spec (t3a (c_v3 c)) 0); [lia | left; reflexivity].
    - intros Hb. pose proof V3 as (_ & _ & _ & Hlen & _).
      assert (Hin : In (t3a (c_v3 c), 4 * t3c (c_v3 c)) (rest_m2 c)) by (apply I6; subst P6; destruct (Z.eqb_spec (t3a (c_v3 c)) 0); [lia | left; reflexivity]).
      eapply (SEQ (t3a (c_v3 c)) (4 * t3c (c_v3 c))); [exact Hin | | exact (SH6 Hb)].
      rewrite cc_gen_length by (unfold Zlen in *; lia). lia.
  Qed.
End Keep.

Definition NT_TBL : list (Z * expr) :=
  [(408, WADD WV_P 216); (576, EVar WV_FF); (616, ELit SHBASE); (624, WADD WV_FF 9040); (648, EVar WV_P);
   (584, EAlu ALU_ADD (EAlu ALU_SRL (WADD WV_P 56) (ELit 3)) (ELit SHBASE)); (592, WADD WV_P 56); (600, WADD WV_P 272);
   (608, WADD WV_FF 9050); (632, WADD WV_P 264); (640, WADD WV_FF 9136);
   (656, EAlu ALU_ADD (EAlu ALU_SRL (WADD WV_P 72) (ELit 3)) (ELit SHBASE)); (664, WADD WV_P 72)].

Definition nt_keys_apart (ks : list Z) : bool :=
  forallb (fun k => (0 <=? k) && ((k + 8 <=? 584) || (616 <=? k)) && ((k + 8 <=? 632) || (648 <=? k))
                    && ((k + 8 <=? 656) || (672 <=? k)))%bool ks.

Section WNT.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HHbp : asan_rt_hyps_bp H.
  Variable LINV : mem -> Prop.

  Hypothesis LINV_cl : forall m m', LINV m -> (forall a, 0 <= a < 2 ^ 64 -> aimg_client a -> m' (wa a) = m (wa a)) -> LINV m'.

  Hypothesis HOWN : rt_own H.
  #[local] Abbreviation ent := (Z * (Z * (Z * Z * Z)))%type.

  Lemma HHnt : asan_rt_hyps H.
  Proof. exact (rt_bp_base H HHbp). Qed.

  Lemma pmxa_nt_m2 : forall (w : pmwA H) s LB LBs m mo c ins tbl ftbl tbl' s' m' mo' (LB' LBm LBr LBm' : list block)
      (bl bc : Z) (ents : list ent) (bl' bc' : Z) (ents' : list ent) (rehashed : bool) (errv' : word),
    pmw_okA H w -> PMXA H LINV w s LB LBs m mo c ins tbl ftbl ->
    keys_nonneg (map fst tbl) = true -> fkeys_ok (map fst ftbl) = true ->
    incl tbl' tbl -> nt_keys_apart (map fst tbl') = true ->
    c_m2 c = (bl, bc, ents) ->
    Permutation LBs (LBm ++ LBr) -> lbl LBr = rest_m2 c ->
    pm_bud (wa_n w) (set_m2A c (bl', bc', ents')) ->
    (rehashed = false -> bl' = bl /\ bc' = bc) -> (rehashed = true -> bc' = bseq_next bc) -> In bc BSEQ -> bc <> BSEQ_LAST ->

    as_RHEAP H s' LB' m' -> Permutation LB' ((wa_LB0 w ++ LBr) ++ LBm') -> Permutation (lbl LBm') (umap_blocks 32 bl' bc' ents') ->
    as_MPRES H mo mo' -> mem_inv asegs m' ->
    stk asegs m' (wa_lo w) (wa_s1 w + 672) -> rw_cells asegs m' (errno_addr (wa_tp w)) [C4 errv'] -> as_rauxv_ok H m' (wa_B w) ->
    xpres H (wa_LB0 w ++ LBr) (wa_s1 w) (nt_X (wa_s1 w) (wa_p w + O_M2)) m m' ->
    @umapx AC_A ASEGS LY_A MI_A 32 (Z * Z * Z) (nval32 ASEGS) (lbl LB') m' (wa_p w + O_M2) bl' bc' ents' -> umap_sh m' 32 (bl', bc', ents') ->
    wr_at asegs m' (wa_p w + O_M2) 40 ->
    as_RFS H (PMLF H w) m' -> ACONST m' -> stack0 m' (wa_lo w) (wa_shi w) ->
    as_AL H s' >= as_AL H s - (if rehashed then ICM (8 * bc') else 0) ->
    PMXA H LINV w s' LB' (LBm' ++ LBr) m' mo' (set_m2A c (bl', bc', ents')) ins tbl' ftbl.
  Proof.
    intros w s LB LBs m mo c ins tbl ftbl tbl' s' m' mo' LB' LBm LBr LBm' bl bc ents bl' bc' ents' rehashed errv'
           OK X0 Hknn Hfk INC KA Em2 PS ELr BUD' NRH RH Hbs Hlast RH' PE' PM' MP' MI' STK' ERR' RA' XP U2' SH2' WR' RFS' AC' S0' AL'.
    pose proof HHnt as HH.
    pose proof (pm_geom H w OK) as G. cbn zeta in G.
    destruct G as (G1 & G2 & G3 & G4 & G5 & G6 & G7 & G8 & G9 & G10 & G11 & G12 & G13).
    pose proof aceil_facts as ((AC1 & AC2) & AC3 & AC4).
    pose proof (p_range H w OK) as [PR1 PR2].
    pose proof (wk_n H w OK) as WN.
    pose proof (pmw_bounds H w OK) as BND.
    pose proof (wk_papp H w OK) as (PA & PA0 & PA16).
    pose proof (xp_geom H HH w OK) as (F1 & F2 & F3 & F4 & F5 & FA & (fp0 & Hfp0 & PF1 & PF2 & PF3 & PF4)).
    pose proof (xa_rheap _ _ _ _ _ _ _ _ _ _ _ _ _ _ X0) as RH0.
    pose proof (xa_own _ _ _ _ _ _ _ _ _ _ _ _ _ _ X0) as [OWN1 OWN2].
    pose proof (xa_al _ _ _ _ _ _ _ _ _ _ _ _ _ _ X0) as (A1 & A2 & A3 & A4).
    set (LBk := wa_LB0 w ++ LBr) in *.
    set (c' := set_m2A c (bl', bc', ents')) in *.
    set (LBs' := LBm' ++ LBr).

    assert (INr : forall b, In b LBr -> In b LBs) by (intros b Hb; apply (Permutation_in _ (Permutation_sym PS)); apply in_or_app; right; exact Hb).
    assert (LBk1 : forall b, In b LBk -> In b LB).
    { intros b Hb. apply (Permutation_in _ (Permutation_sym OWN1)). unfold LBk in Hb. apply in_app_or in Hb. destruct Hb as [Hb|Hb].
      - apply in_or_app; left; exact Hb.
      - apply in_or_app; right; apply in_or_app; left. exact (INr b Hb). }
    assert (LBk0 : forall b, In b (wa_LB0 w) -> In b LBk) by (intros b Hb; unfold LBk; apply in_or_app; left; exact Hb).
    assert (INr' : forall b, In b LBr -> In b LB') by (intros b Hb; apply (Permutation_in _ (Permutation_sym PE')); apply in_or_app; left; unfold LBk; apply in_or_app; right; exact Hb).
    assert (P1 : Permutation LB' (wa_LB0 w ++ LBs' ++ [])).
    { rewrite app_nil_r. unfold LBs'. eapply perm_trans; [exact PE'|]. unfold LBk. rewrite <- app_assoc. apply Permutation_app_head. apply Permutation_app_comm. }
    assert (P2 : Permutation (lbl LBs') (c_blocks c')).
    { unfold LBs'. replace (lbl (LBm' ++ LBr)) with (lbl LBm' ++ lbl LBr) by (unfold lbl; rewrite map_app; reflexivity). rewrite ELr.
      eapply perm_trans; [| apply Permutation_sym; exact (cbk_m2' c (bl', bc', ents'))]. cbn [t3a t3b t3c fst snd]. apply Permutation_app_tail. exact PM'. }
    pose proof (HOWN s' LB' m' RH') as OWNall.
    assert (OWN3 : lb_own LBs' m').
    { eapply lb_own_incl; [| exact OWNall]. intros b Hb. apply (Permutation_in _ (Permutation_sym P1)). apply in_or_app; right. rewrite app_nil_r. exact Hb. }
    assert (MEAS' : pm_meas_ok (wa_n w) LBs') by (apply (pm_meas_of_bud (wa_n w) c' LBs'); [lia | exact BUD' | exact P2]).
    assert (RESV' : pm_cap c' + PM_RESERVE <= po_cost (wa_n w)) by (apply pm_resv_of_bud; [exact WN | exact BUD']).
    assert (AL1 : as_AL H s' >= as_AL H (wa_s0 w) - pm_phi c' - 0).
    { destruct rehashed.
      - pose proof (RH eq_refl) as Ebc'. pose proof (phi_rehash_m2 c bl bc ents bl' ents' Em2 Hbs Hlast) as PG.
        subst bc'. fold c' in PG. clear - A1 AL' PG. lia.
      - destruct (NRH eq_refl) as [-> ->]. pose proof (phi_same_m2 c bl bc ents ents' Em2) as PG. fold c' in PG. clear - A1 AL' PG. lia. }

    assert (FXI : Forall (fun iv : Z * Z => AIMG_TOP <= fst iv) (nt_X (wa_s1 w) (wa_p w + O_M2))).
    { unfold nt_X. repeat apply Forall_cons; try apply Forall_nil; cbn [fst]; unfold O_M2, PARSER_SIZE in *; lia. }
    assert (LI' : LINV m') by (apply (LINV_cl m m' (xa_linv _ _ _ _ _ _ _ _ _ _ _ _ _ _ X0)); eapply (xpres_img H); [exact XP | exact FXI]).
    assert (FX : Forall (xv_ok H w LBs ftbl) (nt_X (wa_s1 w) (wa_p w + O_M2))).
    { unfold nt_X. repeat apply Forall_cons; try apply Forall_nil.
      - right; left. cbn [fst snd]. unfold O_M1, O_M2, PARSER_SIZE. lia.
      - right; right; right; right. cbn [fst snd]. unfold PM_RF_TOP. lia.
      - right; right; right; right. cbn [fst snd]. unfold PM_RF_TOP. lia.
      - right; right; right; right. cbn [fst snd]. unfold PM_RF_TOP. lia. }
    assert (FXW : Forall (fun iv : Z * Z => (snd iv <= wa_ff w + 24 \/ wa_ff w + 16376 <= fst iv) \/ wr_at asegs m' (fst iv) (snd iv - fst iv))
                    (nt_X (wa_s1 w) (wa_p w + O_M2))).
    { unfold nt_X. repeat apply Forall_cons; try apply Forall_nil.
      - right. cbn [fst snd]. replace (wa_p w + O_M2 + 40 - (wa_p w + O_M2)) with 40 by lia. exact WR'.
      - left; right. cbn [fst snd]. lia.
      - left; right. cbn [fst snd]. lia.
      - left; right. cbn [fst snd]. lia. }

    assert (HEQ : forall a, wa_p w + O_M1 <= a < wa_p w + PARSER_SIZE -> (a < wa_p w + O_M2 \/ wa_p w + O_M3 <= a) ->
                    m' (Z_to_bv 64 a) = m (Z_to_bv 64 a)).
    { intros a Ha Hb. apply (XP a); [unfold O_M1, PARSER_SIZE in *; lia|]. split.
      - right; right; right; right; left. unfold O_M1, PARSER_SIZE, AFS_HDR in *. lia.
      - unfold nt_X. cbn [rin_ivs fst snd]. unfold O_M1, O_M2, O_M3, PARSER_SIZE in *. lia. }
    assert (BLKr : forall A n, In (A, n) (rest_m2 c) -> exists q, In (q, A, n) LBr /\ In (q, A, n) LBk /\ In (q, A, n) LB /\ ablock_range H A n).
    { intros A n Hin. rewrite <- ELr in Hin. destruct (lbl_in_inv _ _ _ Hin) as (q & Hq). exists q.
      assert (Hk : In (q, A, n) LBk) by (unfold LBk; apply in_or_app; right; exact Hq).
      split; [exact Hq|]. split; [exact Hk|]. split; [exact (LBk1 _ Hk)|]. exact (ah_blocks H HH _ _ _ _ RH0 (LBk1 _ Hk)). }
    assert (BEQ : forall A n a, In (A, n) (rest_m2 c) -> A <= a < A + n -> m' (Z_to_bv 64 a) = m (Z_to_bv 64 a)).
    { intros A n a Hin Ha. destruct (BLKr A n Hin) as (q & Hq & Hk & HL & (R0 & R16 & Rn & RI & RC & RF & RAPP)).
      apply (XP a); [lia|]. split.
      - right; right; left. exists (q, A, n). split; [exact Hk | cbn; lia].
      - unfold nt_X. cbn [rin_ivs fst snd]. unfold AFS_HDR, O_M2, PARSER_SIZE in *. lia. }
    assert (SEQ : forall A n sbs, In (A, n) (rest_m2 c) -> Z.of_nat (length sbs) <= nsh n -> SHAD m A sbs -> SHAD m' A sbs).
    { intros A n sbs Hin Hlen SH. destruct (BLKr A n Hin) as (q & Hq & Hk & HL & (R0 & R16 & Rn & RI & RC & RF & RAPP)).
      pose proof (aapp_bounds _ _ RAPP Rn) as AB.
      pose proof (sh_nsh_high A n ltac:(lia) Rn ltac:(lia)) as SHH.
      eapply (xpres_SHAD H); [exact XP | exact SH |]. split.
      - right; right; right; left. exists (q, A, n). split; [exact Hk | cbn; lia].
      - pose proof (aapp_disjoint_sh (wa_p w) PARSER_SIZE A n PA ltac:(lia) ltac:(lia) Rn) as D.
        unfold nt_X. repeat apply Forall_cons; try apply Forall_nil; cbn [fst snd]; unfold AHI_LO, O_M2, PARSER_SIZE in *; [destruct D | | |]; lia. }
    assert (LIVE : forall b, In b (rest_m2 c) -> In b (lbl LB) -> In b (lbl LB')).
    { intros [A n] Hin _. destruct (BLKr A n Hin) as (q & Hq & _). exact (lbl_in LB' q A n (INr' _ Hq)). }
    pose proof (pmc_keep_m2 (wa_p w) (lbl LB) (lbl LB') m m' c
                  (xa_m1 _ _ _ _ _ _ _ _ _ _ _ _ _ _ X0) (xa_m3 _ _ _ _ _ _ _ _ _ _ _ _ _ _ X0)
                  (xa_v1 _ _ _ _ _ _ _ _ _ _ _ _ _ _ X0) (xa_v2 _ _ _ _ _ _ _ _ _ _ _ _ _ _ X0) (xa_v3 _ _ _ _ _ _ _ _ _ _ _ _ _ _ X0)
                  (proj1 (xa_sh _ _ _ _ _ _ _ _ _ _ _ _ _ _ X0)) HEQ BEQ SEQ LIVE)
      as (U1' & U3' & SH1' & SH3' & V1' & VS1' & V2' & VS2' & V3' & VS3').
    assert (SHc' : pmc_sh m' c').
    { unfold pmc_sh. unfold c', set_m2A. cbn [c_m1 c_m2 c_m3 c_v1 c_v2 c_v3].
      split; [exact SH1'|]. split; [exact SH2'|]. split; [exact SH3'|]. split; [exact VS1'|]. split; [exact VS2' | exact VS3']. }
    assert (MDh : mdef m' (wa_p w + O_M1) (PARSER_SIZE - O_M1)).
    { eapply mdef_hdrs; [exact U1' | exact U2' | exact U3' | exact V1' | exact V2' | exact V3']. }

    assert (SL' : slots_ok w m' bvmap_empty tbl').
    { pose proof (xa_slots _ _ _ _ _ _ _ _ _ _ _ _ _ _ X0) as SL. unfold slots_ok in *. apply Forall_forall. intros [k e] Hin.
      pose proof (proj1 (Forall_forall _ _) SL (k, e) (INC _ Hin)) as C. cbn [fst snd] in *.
      pose proof (proj1 (forallb_forall _ _) KA k (in_map fst _ (k, e) Hin)) as Kk.
      apply andb_true_iff in Kk as [Kk K3]. apply andb_true_iff in Kk as [Kk K2]. apply andb_true_iff in Kk as [K0 K1].
      apply Z.leb_le in K0. apply orb_true_iff in K1, K2, K3. rewrite !Z.leb_le in K1, K2, K3.
      eapply (xpres_rw_cells H); [exact XP | exact C |]. cbn [cells_size csize Z.of_nat]. split.
      - left. lia.
      - unfold nt_X. repeat apply Forall_cons; try apply Forall_nil; cbn [fst snd]; unfold O_M2, PARSER_SIZE in *; lia. }
    assert (STKf : stk asegs m' (wa_lo w) (wa_sp0 w)).
    { destruct (stk_split asegs m (wa_lo w) (wa_s1 w + 672) (wa_sp0 w) (xa_stk _ _ _ _ _ _ _ _ _ _ _ _ _ _ X0) ltac:(lia)) as [_ ST2].
      apply (stk_join m' (wa_lo w) (wa_s1 w + 672) (wa_sp0 w)); [exact STK' | | lia].
      eapply (xpres_stk H); [exact XP | exact ST2 | lia |].
      unfold nt_X. repeat apply Forall_cons; try apply Forall_nil; cbn [fst snd]; unfold O_M2, PARSER_SIZE in *; lia. }

    eapply (pmxa_xv H HH LINV w s LB LBs m mo c ins tbl ftbl [] 0 s' LB' LBs' m' mo' c' [] 0 LBk (nt_X (wa_s1 w) (wa_p w + O_M2)) [] tbl');
      [exact OK | exact X0 | exact RH' | exact MP' | exact MI' | exact STKf | exists errv'; exact ERR' | exact RA' | exact RFS' | exact AC' | exact S0'
      | exact LI' | apply Forall_nil | rewrite app_nil_r; exact XP | exact FX | exact FXW | exact MDh | exact Hfk | exact SL'
      | exact LBk1 | exact LBk0
      | exact P1 | exact P2 | exact OWN3 | exact MEAS' | apply lb_own_nil | cbn; lia
      | exact AL1 | exact RESV' | unfold PM_RESERVE; lia
      | reflexivity | reflexivity | reflexivity | reflexivity
      | exact U1' | exact U2' | exact U3' | exact V1' | exact V2' | exact V3' | exact SHc' ].
  Qed.

  Lemma bud_emp_m2 : forall n c bl bc (ents : list ent) bl' bc' (ents' : list ent),
    pm_bud n c -> c_m2 c = (bl, bc, ents) -> In bc BSEQ -> bc <> BSEQ_LAST ->
    2 * (Zlength ents + 1) <= n + 2 -> Zlength ents' <= Zlength ents + 1 ->
    (bc' = bc \/ ((bc = 0 \/ Zlength ents = bc) /\ bc' = bseq_next bc)) ->
    pm_bud n (set_m2A c (bl', bc', ents')).
  Proof.
    intros n c bl bc ents bl' bc' ents' BUD E Hbs Hl ACC LEN CASE.
    assert (LE : bseq_next bc <= 2 * bc + 63).
    { clear - Hbs Hl. unfold BSEQ in Hbs. unfold BSEQ_LAST in Hl.
      repeat (destruct Hbs as [<-|Hbs];
        [first [lazymatch goal with |- ?l <= _ => let v := eval vm_compute in l in change l with v end; lia | exfalso; apply Hl; reflexivity] |]).
      destruct Hbs. }
    pose proof (bseq_next_ge2 bc Hbs Hl) as GE. pose proof (LbB_HFind.BSEQ_boundA bc Hbs) as B0.
    assert (N2 : bseq_next 0 = 2) by reflexivity.
    unfold pm_bud in *. unfold set_m2A. cbn [c_m1 c_m2 c_m3 c_v1 c_v2 c_v3 c_tr t3a t3b t3c fst snd] in *.
    rewrite E in BUD. cbn [t3a t3b t3c fst snd] in BUD.
    destruct BUD as ((C1a & C1b & C1c) & D1 & D2 & D3 & D4 & D5 & D6 & D7 & D8).
    unfold Zlength in *.
    refine (conj (conj C1a (conj _ C1c)) (conj D1 (conj _ (conj D3 (conj D4 (conj D5 (conj D6 (conj D7 D8))))))));
      [clear - ACC LEN; lia |].
    destruct CASE as [-> | [[-> | EL] ->]]; [exact D2 | rewrite N2; clear - D2 ACC; lia | clear - D2 ACC LE GE EL B0; lia].
  Qed.

  Lemma pm_nt_emplace : forall (w : pmwA H) s LB LBs m mo c msF R F fc (ty wd enc rid : Z) (Q : config -> Prop),
    pmw_okA H w -> PMXA H LINV w s LB LBs m mo c S_INSTR TBL_EEF44 [] ->
    as_AKREL H s (mkCfg msF mo) -> as_VIS H s msF = MS R F (Z_to_bv 64 0xf5128) fc None m (seg_rom asegs) -> rfull R -> frm_zero fc ->
    regs_tbl w R RT_X3K -> PropExec.getr R 3%bv = wa_gp w -> PropExec.getr R 4%bv = wa_tp w ->
    PropExec.getr R 26%bv = Z_to_bv 64 ty -> 0 <= ty <= 3 -> PropExec.getr R 24%bv = Z_to_bv 64 wd -> 0 <= wd < 2 ^ 64 ->
    PropExec.getr R 15%bv = Z_to_bv 64 enc -> 0 <= enc < 16 ->
    rw_cells asegs m (wa_ff w + 9060) [C4 (Z_to_bv 64 rid)] -> 0 <= rid < 2 ^ 32 ->
    c_tr c = [] -> pm_bud (wa_n w) c -> 2 * (Zlength (t3c (c_m2 c)) + 1) <= wa_n w + 2 ->
    (forall q k, In (q, k) (c_blocks c) -> k <= 2 ^ 40) -> 8 * t3b (c_m2 c) <= 16 * Zlength (t3c (c_m2 c)) + 504 ->
    pi_m2ok (t3c (c_m2 c)) ->
    (forall s' LB' LBs' m' mo' msF' R' F' fc' tbl' (t : Z * Z * list (Z * (Z * (Z * Z * Z)))),
       as_AKREL H s' (mkCfg msF' mo') -> as_VIS H s' msF' = MS R' F' (Z_to_bv 64 0xf5d28) fc' None m' (seg_rom asegs) -> rfull R' -> frm_zero fc' ->
       PMXA H LINV w s' LB' LBs' m' mo' (set_m2A c t) S_INSTR tbl' [] -> incl TBL_X5 tbl' ->
       regs_tbl w R' RT_X5 -> PropExec.getr R' 3%bv = wa_gp w -> PropExec.getr R' 4%bv = wa_tp w ->
       c_tr (set_m2A c t) = [] -> pm_bud (wa_n w) (set_m2A c t) -> (forall q k, In (q, k) (c_blocks (set_m2A c t)) -> k <= 2 ^ 40) ->
       Zlength (t3c (c_m2 c)) <= Zlength (t3c t) <= Zlength (t3c (c_m2 c)) + 1 -> 8 * t3b t <= 16 * Zlength (t3c t) + 504 ->
       pi_m2ok (t3c t) ->
       as_SR H Q (mkCfg msF' mo')) ->
    as_SR H Q (mkCfg msF mo).
  Proof.
    intros w s LB LBs m mo c msF R F fc ty wd enc rid Q OK X0 KR VIS RF FRZ RT G3 G4 R26 Hty R24 Hwd R15 Henc RWrid Hrid
           Htr BUD ACC BLK T3B PIOK K.
    pose proof HHnt as HH.
    pose proof (pm_geom H w OK) as G. cbn zeta in G.
    destruct G as (Q1 & Q2 & Q3 & Q4 & Q5 & Q6 & Q7 & Q8 & Q9 & Q10 & Q11 & Q12 & Q13).
    pose proof aceil_facts as ((AC1 & AC2) & AC3 & AC4).
    pose proof (pmw_bounds H w OK) as BND.
    pose proof (wk_papp H w OK) as (PA & PA0 & PA16). pose proof (p_range H w OK) as [PR1 PR2].
