    assert (Rg2 : PropExec.getr R 2%bv = Z_to_bv 64 (wa_s1 w)) by (rewrite (rt_get w [] R RT_X3K 2%bv _ RT eq_refl); exact ES1).
    assert (Rg9 : PropExec.getr R 9%bv = Z_to_bv 64 (wa_s1 w)) by (rewrite (rt_get w [] R RT_X3K 9%bv _ RT eq_refl); exact ES1).
    assert (Rg8 : PropExec.getr R 8%bv = Z_to_bv 64 (wa_sp0 w)) by (rewrite (rt_get w [] R RT_X3K 8%bv _ RT eq_refl); exact ESP).
    assert (Rg23 : PropExec.getr R 23%bv = Z_to_bv 64 (wa_p w)) by (rewrite (rt_get w [] R RT_X3K 23%bv _ RT eq_refl); exact EP).
    assert (Rg21 : PropExec.getr R 21%bv = Z_to_bv 64 (wa_ff w + 9060)).
    { rewrite (rt_get w [] R RT_X3K 21%bv _ RT eq_refl). exact (ev_add _ WV_FF (wa_ff w) 9060 EF ltac:(lia) ltac:(lia)). }

    pose proof (xa_slots _ _ _ _ _ _ _ _ _ _ _ _ _ _ X0) as SL0.
