    unfold slots_ok, NT_TBL in SLN.
    apply Forall_cons_iff in SLN as [C408 SLN]. apply Forall_cons_iff in SLN as [C576 SLN]. apply Forall_cons_iff in SLN as [C616 SLN].
    apply Forall_cons_iff in SLN as [C624 SLN]. apply Forall_cons_iff in SLN as [C648 SLN]. apply Forall_cons_iff in SLN as [C584 SLN].
    apply Forall_cons_iff in SLN as [C592 SLN]. apply Forall_cons_iff in SLN as [C600 SLN]. apply Forall_cons_iff in SLN as [C608 SLN].
    apply Forall_cons_iff in SLN as [C632 SLN]. apply Forall_cons_iff in SLN as [C640 SLN]. apply Forall_cons_iff in SLN as [C656 SLN].
    apply Forall_cons_iff in SLN as [C664 _].
    cbn [fst snd] in C408, C576, C616, C624, C648, C584, C592, C600, C608, C632, C640, C656, C664.
