    replace (wa_s1 w + 608) with (wa_s1 w + 584 + 8 + 8 + 8) in C608 by lia.
    replace (wa_s1 w + 640) with (wa_s1 w + 632 + 8) in C640 by lia.
    replace (wa_s1 w + 664) with (wa_s1 w + 656 + 8) in C664 by lia.

    assert (FKk : fldA m (wa_ff w + 9060) 4 rid).
    { pose proof (fld_of_cell4 m (wa_ff w + 9060) (Z_to_bv 64 rid) RWrid ltac:(lia)) as FL. rewrite u64_of_Z in FL by lia. exact FL. }
    assert (ESRC : emp_src H LBk (wa_s1 w) (wa_p w + O_M2) (wa_ff w + 9060) 4).
    { split; [| split].
      - right; right; right; right; left. clear - F1 F2. unfold AFS_HDR in *. lia.
      - right; right; right; right; right; left. split; [apply sh_mono; clear - F1; unfold AFS_HDR in *; lia|].
        assert (sh (wa_ff w + 9060) + nsh 4 <= sh (wa_ff w + 9060 + 16)) by (unfold sh, nsh; Z.div_mod_to_equations; lia).
        assert (sh (wa_ff w + 9060 + 16) <= sh (as_FSB H + AFS_SIZE)) by (apply sh_mono; clear - F2; lia). lia.
      - unfold apart. unfold O_M2, PARSER_SIZE in *. clear - PFF. lia. }
    assert (TRd : trace_ok (as_TR H) APC0_FREE (NT_DEL_RA :: map snd ((wa_sp0 w, wa_ra w) :: wa_CH w))).
    { assert (PIN : In (APC0_FREE, [NT_DEL_RA]) PM_PF).
      { unfold PM_PF. apply in_or_app; right. apply in_or_app; right. left. reflexivity. }
      exact (proj1 (Forall_forall _ _) (wk_pf H w OK) (APC0_FREE, [NT_DEL_RA]) PIN). }

    pose proof (pm_phi_le_cap c) as PCc.
    assert (AL0 : 0 <= as_AL H s) by (unfold PM_RESERVE in *; clear - A1 A2 A3 PCc; lia).
    assert (RICM : (bc = 0 \/ Zlength ents = bc) -> ICM (8 * bseq_next bc) <= as_AL H s).
    { intros CASE.
      pose proof (bud_emp_m2 (wa_n w) c bl bc ents 1 (bseq_next bc) ((1, (rid, (0, 0, 0))) :: ents) BUD Em2 Hbs Hlast ACC
                    ltac:(unfold Zlength; cbn [length]; lia) (or_intror (conj CASE eq_refl))) as BUDg.
      pose proof (pm_resv_of_bud (wa_n w) _ WN BUDg) as RESVg.
      pose proof (phi_rehash_m2 c bl bc ents 1 ((1, (rid, (0, 0, 0))) :: ents) Em2 Hbs Hlast) as PG.
      match type of RESVg with pm_cap ?cc + _ <= _ => pose proof (pm_phi_le_cap cc) as PCg end.
      clear - A1 A3 RESVg PG PCg. unfold PM_RESERVE in *. lia. }
    pose proof (pmxa_meas_LB H LINV w s LB LBs m mo c S_INSTR TBL_EEF44 [] [] 0 OK X0) as (M1 & M2 & M3).
    pose proof (pmxa_meas_LB2 H LINV w s LB LBs m mo c S_INSTR TBL_EEF44 [] [] 0 OK X0) as (M4 & M5).
    pose proof (nsmall_bounds (8 * bseq_next bc) ltac:(lia)) as NSB. pose proof (nlg_bounds (8 * bseq_next bc)) as NLB.

    rewrite (rfull_eq R RF) in VIS. rewrite Rg2, Rg9, Rg21, Rg23, G3, G4 in VIS.
    eapply (ah_seq H HH).
    { eapply (LbB_NtE.nt_specA H HHbp
                (PropExec.getr R 1%bv) (wa_gp w) (wa_tp w) (PropExec.getr R 5%bv) (PropExec.getr R 6%bv) (PropExec.getr R 7%bv)
                (PropExec.getr R 8%bv) (PropExec.getr R 10%bv) (PropExec.getr R 11%bv) (PropExec.getr R 12%bv) (PropExec.getr R 13%bv)
                (PropExec.getr R 14%bv) (PropExec.getr R 15%bv) (PropExec.getr R 16%bv) (PropExec.getr R 17%bv)
                (PropExec.getr R 18%bv) (PropExec.getr R 19%bv) (PropExec.getr R 20%bv) (PropExec.getr R 22%bv)
                (PropExec.getr R 24%bv) (PropExec.getr R 25%bv) (PropExec.getr R 26%bv) (PropExec.getr R 27%bv)
                (PropExec.getr R 28%bv) (PropExec.getr R 29%bv) (PropExec.getr R 30%bv) (PropExec.getr R 31%bv)
                F fc msF m mo s LB LBk LBm (PMLF H w) ((wa_sp0 w, wa_ra w) :: wa_CH w)
                (wa_s1 w) (wa_p w + O_M2) bl bc (wa_ff w + 9060) rid (wa_p w + 216) (wa_ff w) (wa_ff w + 9040) ents
                (wa_lo w) (wa_B w) (wa_shi w) errv).
      - replace (wa_p w + O_M2 - 136) with (wa_p w) by (unfold O_M2; lia). exact VIS.
      - exact FRZ.
      - exact U.
      - exact SH2.
      - exact PE.
      - rewrite ELm. apply Permutation_refl.
      - apply (pw_addr_sub8 m (wa_p w) PARSER_SIZE O_M2 40 ADp); unfold O_M2, PARSER_SIZE; try reflexivity; lia.
      - apply (wr_at_of_mdef m (wa_p w) PARSER_SIZE O_M2 40 (xa_pdef _ _ _ _ _ _ _ _ _ _ _ _ _ _ X0)); unfold O_M2, PARSER_SIZE; lia.
      - exists fp0. split; [right; exact Hfp0 | unfold O_M2, PARSER_SIZE in *; lia].
      - unfold O_M2, PARSER_SIZE in *. lia.
      - intros b Hb. pose proof (ah_blocks H HH _ _ _ _ RH Hb) as (_ & _ & _ & _ & _ & RFb & _).
        unfold AFS_HDR, O_M2, PARSER_SIZE in *. clear - RFb PF1 PF2 PF3 PF4. lia.
      - exact FKk.
      - exact ESRC.
      - lia.
      - lia.
      - clear - Q2. Z.div_mod_to_equations. lia.
      - exact Hrid.
      - split; [exact C408 | split; [exact C576 | split; [exact C616 | split; [exact C624 | exact C648]]]].
      - lia.
      - lia.
      - lia.
      - eapply LbB_Conv.rw_cells_cons8_c; [exact C584 |]. eapply LbB_Conv.rw_cells_cons8_c; [exact C592 |].
        eapply LbB_Conv.rw_cells_cons8_c; [exact C600 | exact C608].
      - eapply LbB_Conv.rw_cells_cons8_c; [exact C632 | exact C640].
      - eapply LbB_Conv.rw_cells_cons8_c; [exact C656 | exact C664].
      - clear - ACC WN. unfold Zlength in *. lia.
