    assert (CASE : bc' = bc \/ ((bc = 0 \/ Zlength ents = bc) /\ bc' = bseq_next bc)).
    { destruct rehashed; [right; exact (RHD eq_refl) | left; exact (proj2 (NRH eq_refl))]. }
    assert (BUD1 : pm_bud (wa_n w) (set_m2A c (bl', bc', ents'))) by exact (bud_emp_m2 (wa_n w) c bl bc ents bl' bc' ents' BUD Em2 Hbs Hlast ACC (proj2 LEN) CASE).
    assert (X1 : PMXA H LINV w s1 LB' (LBm' ++ LBr) m1 mo1 (set_m2A c (bl', bc', ents')) S_INSTR TBL_X5 []).
    { eapply (pmxa_nt_m2 w s LB LBs m mo c S_INSTR TBL_EEF44 [] TBL_X5 s1 m1 mo1 LB' LBm LBr LBm' bl bc ents bl' bc' ents' rehashed errv1);
        [ exact OK | exact X0 | vm_compute; reflexivity | reflexivity
        | apply LbB_PmU2K.tbl_incl; vm_compute; reflexivity | vm_compute; reflexivity
        | exact Em2 | exact PS | exact ELr | exact BUD1
        | exact NRH | intros Hrh; exact (proj2 (RHD Hrh)) | exact Hbs | exact Hlast
        | exact RH1 | exact PE1 | exact PM1 | exact MP1 | exact MI1 | exact ST1 | exact ER1 | exact RA1
        | exact XP1 | exact U1 | exact SH1 | exact WR1 | exact RF1 | exact AC1' | exact S01 | exact AL1 ]. }
    assert (VOK : 0 <= t3a (lo32 (PropExec.getr R 26%bv), lo32 (PropExec.getr R 24%bv), lo32 (PropExec.getr R 15%bv)) < 4
                  /\ 0 <= t3c (lo32 (PropExec.getr R 26%bv), lo32 (PropExec.getr R 24%bv), lo32 (PropExec.getr R 15%bv)) < 16).
    { cbn [t3a t3c fst snd]. unfold lo32. rewrite R26, R15, !u64_of_Z by lia. rewrite !Z.mod_small by lia. lia. }
    assert (M2OK : pi_m2ok ents').
    { unfold pi_m2ok in *. destruct inserted.
      - apply Forall_forall. intros e He. apply (Permutation_in _ (INS eq_refl)) in He. destruct He as [<-|He]; [exact VOK|].
        exact (proj1 (Forall_forall _ _) PIOK e He).
      - destruct (NINS eq_refl) as (v0 & l1 & l2 & E1 & E2 & _). rewrite E2. rewrite E1 in PIOK.
        apply Forall_app in PIOK as [PL PR]. apply Forall_cons_iff in PR as [_ PR].
        apply Forall_app. split; [exact PL|]. apply Forall_cons; [exact VOK | exact PR]. }
    assert (MAC : 8 * bc' <= 16 * Zlength ents' + 504).
    { destruct rehashed.
      - destruct (RHD eq_refl) as [Hc ->]. destruct inserted.
        + pose proof (Permutation_length (INS eq_refl)) as EL. unfold Zlength in *. cbn [length] in EL. rewrite EL.
          destruct Hc as [-> | Hc]; [change (bseq_next 0) with 2; lia | lia].
        + destruct (NINS eq_refl) as (_ & _ & _ & _ & _ & E). discriminate E.
      - destruct (NRH eq_refl) as [-> ->]. lia. }
    assert (BLK1 : forall q k, In (q, k) (c_blocks (set_m2A c (bl', bc', ents'))) -> k <= 2 ^ 40).
    { intros q k Hq. apply (Permutation_in _ (cbk_m2' c (bl', bc', ents'))) in Hq. cbn [t3a t3b t3c fst snd] in Hq.
      apply in_app_or in Hq as [Hq|Hq].
      - unfold umap_blocks in Hq. apply in_app_or in Hq as [Hq|Hq].
        + destruct (bc' =? 0); [destruct Hq | destruct Hq as [Hq|[]]]. injection Hq as <- <-.
          destruct CASE as [-> | [_ ->]]; lia.
        + apply in_map_iff in Hq as (e & Ee & _). injection Ee as <- <-. lia.
      - apply (BLK q k). apply (Permutation_in _ (Permutation_sym (cbk_m2 c))). apply in_or_app; right; exact Hq. }

    eapply (K s1 LB' (LBm' ++ LBr) m1 mo1 ms1 _ _ _ TBL_X5 (bl', bc', ents'));
      [ exact KR1 | exact VIS1 | apply rfull_mkR | exact FRZ1 | exact X1 | apply incl_refl | | reflexivity | reflexivity
      | exact Htr | exact BUD1 | exact BLK1 | exact LEN | exact MAC | exact M2OK ].
    unfold regs_tblX, RT_X5. repeat apply Forall_cons; try apply Forall_nil; cbn [fst snd].
    - transitivity (Z_to_bv 64 (wa_s1 w)); [reflexivity | symmetry; exact ES1].
    - transitivity (PropExec.getr R 8%bv); [reflexivity | exact (rt_get w [] R RT_X3K 8%bv _ RT eq_refl)].
    - transitivity (Z_to_bv 64 (wa_s1 w)); [reflexivity | symmetry; exact ES1].
    - transitivity (Z_to_bv 64 (wa_ff w + 9040)); [reflexivity | symmetry; exact (ev_add _ WV_FF (wa_ff w) 9040 EF ltac:(lia) ltac:(lia))].
    - transitivity (PropExec.getr R 20%bv); [reflexivity | exact (rt_get w [] R RT_X3K 20%bv _ RT eq_refl)].
    - transitivity (Z_to_bv 64 (wa_p w + O_M2 - 136)); [reflexivity |].
      replace (wa_p w + O_M2 - 136) with (wa_p w) by (unfold O_M2; lia). symmetry; exact EP.
    - transitivity (Z_to_bv 64 (wa_p w + 216)); [reflexivity | symmetry; exact (ev_add _ WV_P (wa_p w) 216 EP ltac:(lia) ltac:(lia))].
    - transitivity (Z_to_bv 64 (wa_ff w)); [reflexivity | symmetry; exact EF].
  Qed.
